import requests
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/'
queries=['("retrodifferentiation" AND liver AND cytokine)','(hepatocyte-like AND progenitor AND cytokine AND liver cancer)','(hepatocellular carcinoma AND inflammatory cytokines AND progenitor cells AND dedifferentiation)']
for q in queries:
 r=requests.get(base+'esearch.fcgi',params={'db':'pubmed','term':q,'retmax':10,'retmode':'json'},timeout=25)
 print('\nQUERY',q,'STATUS',r.status_code)
 js=r.json()['esearchresult']; ids=js.get('idlist',[]); print('COUNT',js.get('count'),'IDS',ids)
 if ids:
  x=requests.get(base+'esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=25).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
